INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, "2020/04/30 12:00:00", 24001, 0.0, 0, 1, 0.0, "あたしだって\nやるときはやるよ！", 0.0, 10040, "リン", 1, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, "2020/04/30 12:00:00", 24002, 0.0, 1, 1, 0.0, "ふぅ…\nこれであたしの仕事は\n終わりだね", 0.0, 10040, "リン", 1, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, "2020/04/30 12:00:00", 24003, 0.0, 2, 1, 0.0, "終わった終わった\n一人でもなんとか\nなるもんだね", 0.0, 10040, "リン", 1, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, "2020/04/30 12:00:00", 24004, 0.0, 3, 2, 0.0, "やったね！\nこれでようやく\nサボれるよ…", 0.0, 10040, "リン", 2, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, "2020/04/30 12:00:00", 24005, 0.0, 4, 1, 0.0, "チーズが欲しいなら\nきちんと働いて\n買いに来なよ", 0.0, 10040, "リン", 1, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, "2020/04/30 12:00:00", 24006, 0.0, 5, 2, 0.0, "あたしを敵に回した\n恐ろしさ\n思い知ったか！", 0.0, 10040, "リン", 2, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, "2020/04/30 12:00:00", 24007, 0.0, 6, 2, 0.0, "あたしも意外と\nやるもんでしょ？", 0.0, 10040, "リン", 2, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, "2020/04/30 12:00:00", 24008, 0.0, 7, 4, 0.0, "疲れた…\nねずみの逃げ足\n速すぎるよ…", 0.0, 10040, "リン", 4, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, "2020/04/30 12:00:00", 24009, 0.0, 8, 4, 0.0, "このままじゃ\nまっひ～に\n叱られちゃうよ", 0.0, 10040, "リン", 4, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, "2020/04/30 12:00:00", 24010, 0.0, 9, 4, 0.0, "まじめに\nやったんだけどな…\n悔しいな～", 0.0, 10040, "リン", 4, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, "2020/04/30 12:00:00", 24011, 0.0, 10, 4, 0.0, "やられた…\nねずみって意外と\nてごわいね", 0.0, 10040, "リン", 4, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, "2020/04/30 12:00:00", 24012, 0.0, 11, 4, 0.0, "おのれ～\nあたしのチーズを\n盗みやがって～！", 0.0, 10040, "リン", 4, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (102601, "2020/04/30 12:00:00", 24013, 0.0, 12, 4, 0.0, "疲れた…\nけど、次こそは\n守り抜くよ…", 1.81, 10040, "リン", 1, "2030/12/17 14:59:59", 24);
